export default async ({ input, request }) => {
  const response = await request(input.endpoint_url);
  if (response.status < 200 || response.status >= 300) {
    throw new Error("Observations endpoint returned an unsuccessful status");
  }
  const data = JSON.parse(Buffer.from(response.body_base64, "base64").toString("utf8"));
  if (!data || !Object.prototype.hasOwnProperty.call(data, "observations") || !Array.isArray(data.observations)) {
    throw new Error("Required top-level observations array is missing or invalid");
  }
  const items = data.observations.slice(0, 20).map((observation) => {
    if (!observation || typeof observation !== "object") {
      throw new Error("Invalid observation");
    }
    for (const field of ["observationId", "headline", "published", "permalink"]) {
      if (typeof observation[field] !== "string" || observation[field].trim() === "") {
        throw new Error("Observation is missing required field: " + field);
      }
    }
    if (!Number.isFinite(Date.parse(observation.published))) {
      throw new Error("Observation has an invalid published timestamp");
    }
    return {
      external_id: observation.observationId,
      title: observation.headline,
      source_uri: observation.permalink,
      published_at: observation.published,
      excerpt: "",
      snapshots: [],
      evidence: []
    };
  });
  return { items, cursor: {} };
};

